import copy
import re
import xmltodict
from datetime import datetime
from pathlib import Path
from abc import abstractmethod
from auto_config.generator.config_file_generic import ConfigFileGeneric
from auto_config.generator.utils.dist_names_generator import DistNameGenerator, sorting_key
from auto_config.generator.utils.get_enb_params import get_enb_params
from auto_config.generator.utils.logger import logger
from auto_config.generator.utils.telemetry import tl_update
from auto_config.generator.utils.utils import get_env, is_nr


class BTS(ConfigFileGeneric):

    def __init__(self, for_n1=False):
        self._file_content = []
        self._filename_suffix = 'GOLDEN' if not for_n1 else 'REL_N1'
        self.fail_on_error = get_env("AC_FAIL_ON_ERROR")
        self.custom_params_flag = False

    @abstractmethod
    def update_managed_object_occurrences(self, enb_ent_config, execution_config, pddb_topology, epc_config):
        pass

    @abstractmethod
    def update_starting_index(self, enb_ent_config, pddb_params, pddb_topology):
        pass

    @abstractmethod
    def add_specific_mocs(self, dist_names, enb_ent_config, execution_config):
        pass

    @abstractmethod
    def get_params_generator_factory(self):
        pass

    def fetch_content(
        self, enb_ent_config, execution_config, env_config, epc_config,
        pddb_release, pddb_parser
    ):
        pddb_topology = pddb_parser.get_pddb_topology_copy()
        logger.info(f"Merging default pddb params with default BTS params for release {pddb_release}")
        pddb_params = pddb_parser.merge_moc_mandatory_params(get_enb_params(pddb_release))

        self.update_managed_object_occurrences(enb_ent_config, execution_config, pddb_topology, epc_config)
        self.update_starting_index(enb_ent_config, pddb_params, pddb_topology)

        dist_name_generator = DistNameGenerator(pddb_params, pddb_topology, enb_ent_config, nr=is_nr(enb_ent_config))
        dist_names = dist_name_generator.generate_dist_names()

        self.add_specific_mocs(dist_names, enb_ent_config, execution_config)

        dist_names = sorted(dist_names, key=sorting_key)
        logger.debug('Following Managed Objects has been generated:\n --- ' + '\n --- '.join(dist_names))

        managed_objects = []
        params_generator_factory = self.get_params_generator_factory()

        if 'custom_params' in enb_ent_config:
            self.custom_params_flag = True
            for dn in dist_names:
                bts_id = re.search(r'MRBTS-(\d+)', dn).group(1)

        for dist_name in dist_names:

            # last part of dist_name, e.g. MRBTS-1/MNL-1/MNLENT-1/SYNC-2/TIME-1 -> TIME-1
            managed_object = dist_name.split('/')[-1] if '/' in dist_name else dist_name
            mo_name = managed_object.split('-')[0]

            # make copy of pddb_params this object
            mo_params = copy.deepcopy(pddb_params[mo_name])

            # get proper ParamsGenerator;
            mo_params_generator = params_generator_factory(mo_name)(dist_name, mo_params, enb_ent_config, pddb_topology, pddb_parser)

            mo_xml_formatted = mo_params_generator.generate_section_content(
                execution_config,
                env_config=env_config,
                epc_config=epc_config
            )

            class_map, class_version = pddb_parser.get_pddb_classes()

            mo_xml_formatted.update({
                '@class': class_map[mo_name],
                '@distName': dist_name,
                '@operation': 'create',
                '@version': class_version[mo_name]
            })

            if self.custom_params_flag:
                self.add_custom_params(dist_name, bts_id, enb_ent_config, mo_xml_formatted)

            self.verify_xml_empty_text(mo_xml_formatted)
            managed_objects.append(mo_xml_formatted)

        del pddb_params, pddb_topology
        return managed_objects

    def add_custom_params(self, dist_name, bts_id, enb_ent_config, mo_xml_formatted):
        for dn, custom_params in enb_ent_config['custom_params'].items():
            dn = re.sub(r'(?<=MRBTS-|NRBTS-)\$\{\s*BTS_ID\s*\}', str(bts_id), dn)
            if "${ALL}" in dn:
                dn = dn.replace("${ALL}", "")
                srch = re.search(r'^(.*-)\d+$', dist_name)
                if srch:
                    dist_name_prefix = srch.group(1)
            else:
                dist_name_prefix = dist_name

            if dist_name_prefix == dn:
                for custom_param_name, custom_param_value in custom_params.items():
                    if isinstance(custom_param_value, list):
                        mo_params = mo_xml_formatted['list'] if isinstance(mo_xml_formatted['list'], list) else [mo_xml_formatted['list']]
                        mo_xml_formatted['list'] = self.update_param_list(mo_params, custom_param_name, custom_param_value)
                    elif isinstance(custom_param_value, dict):
                        for custom_subparam_name, custom_subparam_value in custom_param_value.items():
                            mo_params = mo_xml_formatted['list'] if isinstance(mo_xml_formatted['list'], list) else [mo_xml_formatted['list']]
                            mo_xml_formatted['list'] = self.update_param_item_list(mo_params, custom_param_name,
                                                                                   custom_subparam_name, custom_subparam_value)
                    else:
                        if 'p' in mo_xml_formatted:
                            mo_params = mo_xml_formatted['p'] if isinstance(mo_xml_formatted['p'], list) else [mo_xml_formatted['p']]
                            mo_xml_formatted['p'] = self.update_param_text(mo_params, custom_param_name, custom_param_value)

    def verify_xml_empty_text(self, mo_xml):
        dist_name = mo_xml['@distName']
        # logger.info("### [{}] MO XML={}".format(dist_name, mo_xml))
        for _key, val in mo_xml.items():
            self.verify_xml_empty_text_item(val, dist_name)

    def verify_xml_empty_text_item(self, item, dist_name):
        # logger.info("### [{}] MO XML ITEM={}".format(dist_name, item))
        item_name = item['@name'] if '@name' in item else None
        if isinstance(item, list):
            for sub_item in item:
                self.verify_xml_empty_text_item(sub_item, dist_name)
        elif isinstance(item, dict):
            for key, val in item.items():
                if key == '#text':
                    if val == '':
                        if '@name' in item:
                            item_name = item['@name']
                        self.error(f"Empty xml text in {dist_name} for {item_name}")
                else:
                    self.verify_xml_empty_text_item(val, dist_name)

    def to_file(self,
                output_dir, execution_config,
                ue_config, enb_config, env_config, epc_config,
                hw_config, pddb_release, pddb_parser):
        for bts_key, bts_ent_config in sorted(enb_config.items()):
            bts_num = re.search(r'\d+', bts_key).group(0)
            logger.info(f"Generating SCFC file for {type(self).__name__}{bts_num} ({bts_ent_config['id']})")

            managed_objects = self.fetch_content(
                enb_ent_config=bts_ent_config,
                execution_config=execution_config,
                env_config=env_config,
                epc_config=epc_config,
                pddb_release=pddb_release,
                pddb_parser=pddb_parser,
            )

            scfc_dict = {
                'raml': {'@version': '2.1',
                         '@xmlns': 'raml21.xsd',
                         'cmData': {
                             '@scope': 'all',
                             '@type': 'plan',
                             'header': {
                                 'log': {
                                     '@action': 'created',
                                     '@dateTime': f'{datetime.now().strftime("%Y-%m-%dT%H:%M:%S")}'
                                 }
                             },
                             'managedObject': managed_objects
                         }}
            }

            filename = 'TL{}_1.0_{}_{}.xml'.format(
                bts_ent_config['id'], execution_config['pddb_release'], self._filename_suffix
            )
            logger.info("Saving SCFC file with name {}".format(filename))
            filepath = Path(output_dir) / filename
            with filepath.open(mode='w', encoding='utf-8') as f:
                header = '<?xml version="1.0" encoding="UTF-8" standalone="no"?>\n'
                f.write(header + xmltodict.unparse(scfc_dict, pretty=True, indent='  ', full_document=False))

    def error(self, msg):
        logger.error(msg)
        if self.fail_on_error:
            raise Exception(msg)
        tl_update("param_value_out_of_range", 1, {"status": "failure", "exception": msg})

    def update_param_list(self, mo_param_list, custom_param_name, custom_param_value):
        for mo_param in mo_param_list:
            if mo_param.get('@name') == custom_param_name:
                mo_param['p'] = custom_param_value
                return mo_param_list
        mo_param_list.append({'@name': custom_param_name, 'p': custom_param_value})
        return mo_param_list

    def update_param_text(self, mo_param_list, custom_param_name, custom_param_value):
        for mo_param in mo_param_list:
            if mo_param.get('@name') == custom_param_name:
                mo_param['#text'] = custom_param_value
                return mo_param_list
        mo_param_list.append({'@name': custom_param_name, '#text': custom_param_value})
        return mo_param_list

    def update_param_item_list(self, mo_param_list, custom_param_name, custom_subparam_name, custom_subparam_value):
        for mo_param in mo_param_list:
            if mo_param.get('@name') == custom_param_name:
                for mo_item_subparams in mo_param['item']:
                    mo_subparams = mo_item_subparams['p'] if isinstance(mo_item_subparams['p'], list) else [mo_item_subparams['p']]
                    for mo_subparam in mo_subparams:
                        if mo_subparam.get('@name') == custom_subparam_name:
                            mo_subparam['#text'] = custom_subparam_value
                            return mo_param_list
                    mo_subparams.append({'@name': custom_subparam_name, '#text': custom_subparam_value})
                    mo_item_subparams['p'] = mo_subparams
                    return mo_param_list
        mo_param_list.append({'@name': custom_param_name, 'item': [{'p': [{'#text': custom_subparam_value,
                                                                           '@name': custom_subparam_name}]}]})
        return mo_param_list
